UPDATE RESERVATIONS
SET user_id         = #{userId},
    reserved_status = 'RESERVED',
    reserved_at     = NOW(),
    upt_id          = #{uptId},
    upt_ip          = #{uptIp}
WHERE reservation_id = #{reservationId}
  AND round_id = #{roundId}
  AND seat_id  = #{seatId}
  AND user_id IS NULL

